-- Auto-generated by Doriax Editor

local PlayerScript = {
    properties = {
        {
            name = "speed",
            displayName = "Speed",
            type = "float",
            default = 3.0
        },
        {
            name = "jump_force",
            displayName = "Jump Force",
            type = "float",
            default = 6.0
        }
    }
}

local camera_y = 0.0
local is_Cursor_locked = false

local last_mouse_x = 0.0

function PlayerScript:init()
    RegisterEngineEvent(self, "onUpdate")
end

function PlayerScript:onUpdate()
    local mousePos = Input.getMousePosition()


    local body = Body3D(self.scene, self.entity)
    local obj = Object(self.scene, self.entity)
   
    local camera_rotation = 0.0
    
    body.rotation = Quaternion(0.0, camera_rotation, 0.0)
   
   
    if is_Cursor_locked == true then
            local delta_x = mousePos.x - last_mouse_x
            
            camera_y = camera_y + (delta_x * 0.03)
            
            
            body.rotation = Quaternion(0.0, -camera_y, 0.0)
            
    end
    
   
    local currentVelocity = body.linearVelocity
    
     
    
    local moveZ = 0.0
    local moveX = 0.0
    local moveY = currentVelocity.y

    if Input.isKeyPressed(Input.KEY_W) then
           moveZ = -self.speed
    elseif Input.isKeyPressed(Input.KEY_S) then
           moveZ = self.speed
    end
    
    if Input.isKeyPressed(Input.KEY_A) then
           moveX = -self.speed
    elseif Input.isKeyPressed(Input.KEY_D) then
           moveX = self.speed
    end
    
    
    local startPos = body.position
            
    local downDirection = Vector3(0.0, -1.05, 0.0)
    
    local floor_ray = Ray(startPos, downDirection)
    
    local hit = floor_ray:intersects(self.scene, RayFilter.BODY_3D, self.entity)
            if hit and hit.hit then
                if Input.isKeyPressed(Input.KEY_SPACE) then
                        moveY = self.jump_force
                end  
            end
    
    local currentRotation = body.rotation
    local forwardDir = currentRotation:zAxis()
    local rightDir = currentRotation:xAxis()
    local worldMovement = (rightDir * moveX) + (forwardDir * moveZ)
    
    body.linearVelocity = Vector3(worldMovement.x, moveY, worldMovement.z)
    
    
    
    if Input.isMousePressed(Input.MOUSE_BUTTON_MIDDLE) then
            if is_Cursor_locked == false then
                    is_Cursor_locked = true
                    
                    last_mouse_x = mousePos.x
            end
    end
    if Input.isMousePressed(Input.KEY_ESCAPE) then
            if is_Cursor_locked == true then
                    is_Cursor_locked = false
            end
    end
    last_mouse_x = mousePos.x
end

return PlayerScript